import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = read(scanner);
        int height = input[0];
        int num = input[1] - 1;

        String binStr = Integer.toBinaryString(num);
        binStr = "0".repeat(height - binStr.length()) + binStr;

        StringBuilder outputStr = new StringBuilder();
        for (int index = 0; index < height; index++) {
            if (index != 0 && binStr.charAt(index - 1) == '0') {
                outputStr.append(binStr.charAt(index) == '0' ? '1' : '0');
            } else {
                outputStr.append(binStr.charAt(index));
            }
        }

        long totalCount = 0;
        for (int index = 0; index < height; index++) {
            totalCount += 1;
            if (outputStr.charAt(index) == '1') {
                totalCount += Math.pow(2, height - index) - 1;
            }
        }
        System.out.println(totalCount);
        scanner.close();
    }

    public static int[] read(Scanner scanner) {
        String line = scanner.nextLine().trim();
        String[] parts = line.split("\\s+");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}
